  const messageType = data.messageType || Object.keys(msg)[0] || '';
  let text = '';
  if (messageType === 'conversation' || messageType === 'extendedTextMessage') {
    text = msg.conversation || ((msg.extendedTextMessage || {}).text) || '';
  }
  const t = text.trim().toLowerCase();
  let action = '';
  if (t === '1' || t === 'odobri') { action = 'odobri'; }
  else if (t === '2' || t === 'zavrni') { action = 'zavrni'; }
  else { action = 'unknown'; }
  return [{json: {phone, remoteJid, route: 'manager', text, action, mgrPhone, messageKey: data.key, messageData: msg}}];
}
// --- End manager detection ---

const msg = data.message || {};
const messageType = data.messageType || Object.keys(msg)[0] || '';
let route = 'skip', text = '', responseType = '';
if (messageType === 'audioMessage' || messageType === 'pttMessage') {
  route = 'audio';
} else if (messageType === 'buttonsResponseMessage') {
  responseType = ((msg.buttonsResponseMessage || {}).selectedButtonId || '').toLowerCase();
  if (!['confirm','edit','cancel'].includes(responseType)) responseType = 'unknown';
  route = 'response';
} else if (messageType === 'conversation' || messageType === 'extendedTextMessage') {
  text = msg.conversation || ((msg.extendedTextMessage || {}).text) || '';
  const t = text.trim().toLowerCase();
  if (t === '1' || t === 'potrdi') { route = 'response'; responseType = 'confirm'; }
  else if (t === '2' || t === 'popravi') { route = 'response'; responseType = 'edit'; }
  else if (t === '3') { route = 'response'; responseType = 'add_photos'; }
