function parseHours(text) {
  const numM = text.match(/(\d+(?:[.,]\d+)?)\s*(?:uro|uri|ure|ur\b)/i);
  if (numM) return parseFloat(numM[1].replace(',', '.'));
  // Slovenian cardinal words
  const words = {
    'ena': 1, 'eno': 1, 'eni': 1,
    'dve': 2, 'dva': 2, 'dveh': 2,
    'tri': 3, 'treh': 3,
    'stiri': 4, 'stirib': 4,
    'pet': 5, 'petih': 5,
    'sest': 6, 'sestih': 6,
    'sedem': 7, 'sedmih': 7,
    'osem': 8, 'osmih': 8,
