    'deset': 10, 'desetih': 10,
    'enajst': 11, 'enajstih': 11,
    'dvanajst': 12, 'dvanajstih': 12,
    'trinajst': 13, 'stirinajst': 14,
    'petnajst': 15, 'sestnajst': 16,
    'sedemnajst': 17, 'osemnajst': 18,
    'devetnajst': 19, 'dvajset': 20,
